141			if err != nil {
142				fmt.Fprintf(os.Stderr, "rules show: %v\n", err)
143				os.Exit(1)
144			}
145			writeJSON(version)
146		case "register":
147			if len(args) != 3 {
148				fmt.Fprintln(os.Stderr, "usage: mevwatch rules register <archive-dir> <spec-file>")
149				os.Exit(2)
150			}
151			var raw []byte
152			var err error
153			if args[2] == "-" {
154				raw, err = io.ReadAll(os.Stdin)
155			} else {
156				raw, err = os.ReadFile(args[2])
157			}
158			if err != nil {
159				fmt.Fprintf(os.Stderr, "rules register: %v\n", err)
160				os.Exit(1)
