15	// Offline alerting turns conclusions already stored in an archive into
16	// alert processing records. It never re-runs detection: a record always
17	// reflects the finding, the rule version and the parameters that were in
18	// force when the block was archived.
19	
20	// Alert statuses. A finding above the generation threshold becomes an
21	// "alert"; a finding that matches one or more registered suppression
22	// conditions at its block height becomes "suppressed" instead.
23	const (
24		AlertStatusAlert      = "alert"
25		AlertStatusSuppressed = "suppressed"
26	)
27	
28	// Suppression condition kinds.
29	const (
30		SuppressSandwich     = "sandwich"
31		SuppressDisplacement = "displacement"
