743			case err == nil:
744				succeeded++
745			case errors.Is(err, ErrBusy):
746				busy++
747			default:
748				t.Fatalf("unexpected error: %v", err)
749			}
750		}
751		if succeeded != 1 {
752			t.Fatalf("got %d successful generators and %d busy, want exactly 1 success", succeeded, busy)
753		}
754		hist, err := AlertHistory(dir, "1", "ops", 0, 100)
755		if err != nil {
756			t.Fatal(err)
757		}
758		if len(hist) != 2 {
759			t.Fatalf("history holds %d records, want exactly 2 (no duplicates, no loss)", len(hist))
760		}
761		seen := map[alertKey]bool{}
762		for _, r := range hist {
763			k := r.identity()
764			if seen[k] {
765				t.Fatalf("duplicate processing record: %+v", k)
766			}
767			seen[k] = true
768		}
769	}
770	
771	func TestGenerateOnlyReturnsNewRecords(t *testing.T) {
772		dir := t.TempDir()
773		mustReplay(t, dir, twoFindingsInput)
774		// First generation with a suppression in place: one alert, one suppressed.
775		spec := `{"id":"s","chainId":"1","pool":"p1","kind":"sandwich","channel":"ops","startHeight":10,"endHeight":10,"reason":"r"}`
776		if _, _, err := RegisterSuppression(dir, []byte(spec)); err != nil {
